"""Primary-supported conference counterparts and casting-source first pass."""
import json
import ledger as L
from review_batch_0001 import evidence

def main():
 pubs={p['registry_key']:p for p in L.read('publication_reviews')};root=L.ROOT/'assets/research-20261105'
 rapid=evidence(L.HERE/'fnano2013_rapid_metadata.json','https://pubmed.ncbi.nlm.nih.gov/23239734/','Primary title/four authors/DOI/2012-12-14 issue date and author abstract; subsequent direct page showed only footer')
 key='10.1126/science.1229919';assert key not in pubs or pubs[key].get('run_id')=='fnano2013-counterparts'
 p=pubs.get(key,dict(registry_key=key,registry_id=None,doi=key,canonical_work_id='work:'+key,canonical_work_status='provisional_unreconciled',version_links=[],legacy_record={}))
 p.update(title='Rapid folding of DNA into nanoscale shapes at constant temperature',authors=['Jean-Philippe J. Sobczak','Thomas G. Martin','Thomas Gerling','Hendrik Dietz'],publication_type=['journal_article'],date_evidence={'date':'2012-12-14','meaning':'Primary issue date; earlier first-online date not yet verified','source':rapid,'primary_verified':True},review_stage='metadata_screened',relevance='design_bearing',design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',evidence=[rapid],rationale='Author abstract reports rapid cooperative folding of a long DNA template into3Dobjects at constant temperature. Exact FNANO2013 talk title and four author names agree. New journal record found through conference history; individual designs, parentage, main/SI and complete synthesis sources remain unreviewed. Conference2013date does not replace journal2012date.',unresolved_questions=['Acquire main/SI/native designs and inspect each core and sequence variant.','Verify first-online date and exact conference overlap; retain distinct identities.'],reviewer='Codex primary metadata/abstract inspection',run_id='fnano2013-counterparts',date=L.DATE)
 L.upsert('publication_reviews',p,'Add absent pre2020 paper discovered through conference program')
 si=evidence(root/'sun-2014-casting-si.pdf','https://yin.hms.harvard.edu/publications/2014.casting.sup1.pdf','121-page SI PDFp7 S2.2 folding; p58 S10.1 optimization; p70 SupplementII contents; p71 scaffold heading; contents survey pp2–6')
 main_ev=evidence(root/'sun-2014-casting-main.pdf','https://yin.hms.harvard.edu/publications/2014.casting.pdf','10-page publisher copy: PDFpp1–4 summary, computational design, assembly stages and figure captions; not full article')
 meta=evidence(L.HERE/'fnano2013_counterpart_web.json','https://pubmed.ncbi.nlm.nih.gov/25301973/','Primary seven authors, first-online2014-10-09 versus issue2014-11-07')
 key='10.1126/science.1258361';p=pubs[key]
 note='Origami molds contain cavities and nucleating Au seeds; barrel and two lids are separately assembled components before closed mold assembly, and metal casts are material products rather than DNA core variants. Main depicts three cuboid cavities21x16x30,21x16x20,16x16x20nm, triangular/circular molds and Y/QD composites. SI S2.2 specifies mutatedP8064; SupplementII lists scaffold, barrel/ring/lid and composite-modified sequence sections. S10.1 explicitly says all main-text molds use square-lattice packing and multilayer walls; honeycomb hexagonal prototype distorted during growth. Single-layer wall, low-crossover triangular designs and small ring trials are failed/suboptimal variants, not equivalent successful cores. Source tables/maps not fully checked. PDF extraction reports Illegal URI-type link warning; figure/routing integrity not certified.'
 qs=['Inspect all SupplementII diagrams/sequences and modifiedP8064; map each barrel/lid/core and connector/seed handle composition.','Keep successful square-lattice and failed honeycomb prototypes separate; independently check source geometry and scope.','Reconcile2013poster with2014journal at design/result level; full author list differs.','Enumerate full references, inspect remaining main sections and locate native files.']
 p.update(review_stage='design_sources_reviewed',relevance='design_bearing',publication_type=['journal_article'],design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',evidence=[main_ev,si,meta],date_evidence={'date':'2014-10-09','meaning':'First-online, distinct from2014-11-07issue','source':meta,'primary_verified':True},rationale=note,unresolved_questions=qs,reviewer='Codex named primary and SI section inspection',run_id='fnano2013-counterparts',date=L.DATE)
 L.upsert('publication_reviews',p,'Review actual casting sources with component/material/lattice boundaries')
 L.upsert('design_evidence',dict(design_id='RDE0036',legacy_record={},review_run='fnano2013-counterparts',catalog_eligibility='unresolved',publication_keys=[key],named_objects=['Cuboid barrel/lid molds','Triangular and ring molds','Y and QD composite modifications','Failed or suboptimal single-layer/honeycomb/small-cavity trials'],variant_links=[],relationships=[],lattice_decision='Main-text molds explicitly square lattice in SI S10.1(c); failed hexagonal prototype honeycomb; actual maps pending',evidence=[main_ev,si],source_files=[main_ev,si],core_variant_composition=note,source_completeness='not_verified',outstanding_checks=qs,review_stage='source_reviewed',run_id='fnano2013-counterparts',date=L.DATE,identity_status='provisional family; individual core/component identity unresolved'),'Preserve source-backed family without fabricating complete core enumeration')
 for author,title,target,ev,note in [
 ('Jean-Philippe Jacques Sobczak','Rapid folding of DNA into nanoscale shapes at constant temperature','10.1126/science.1229919',rapid,'Exact title/four-author group matches2012paper; exact conference results overlap pending.'),
 ('Wei Sun','Casting Metal Structures within Programmable DNA Molds',key,meta,'Related title and all three program authors Sun/Guan/Yin appear in seven-author2014paper; likely counterpart, not established identical scope.')]:
  source=next(x for x in L.read('publication_reviews') if x.get('run_id')=='fnano-2013' and x.get('title')==title)
  L.upsert('discovery_edges',dict(edge_id='fnano2013:counterpart:'+source['registry_key'],source_key=source['registry_key'],target_key=target,relation='possible_journal_counterpart',evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator=note,reconciliation_state='bibliographic_candidate_supported; exact_scope_identity_pending',run_id='fnano2013-counterparts',date=L.DATE),'Link primary-supported counterpart without canonical merge')
  source['evidence'].append(ev);source['unresolved_questions'].insert(0,'Candidate '+target+': '+note);L.upsert('publication_reviews',source,'Retain counterpart evidence and conference uncertainty')
 L.upsert('discovery_runs',dict(run_id='fnano2013-counterparts',route='conference_reconciliation',query_or_seed='FNANO2013rapid-folding and casting-molds leads',source_url=rapid['url'],date=L.DATE,pagination={'named_leads_reviewed':2,'complete':False},provider_total=None,retrieved_count=2,deduplicated_additions=1,additions_unit='One previously absent journal paper; one existing journal source review',evidence=[rapid,meta,main_ev,si],failures=['Rapid direct PubMed rendering later returned footer only; indexed primary metadata retained.'],closure_state='in_progress',checkpoint='Inspect exact conference overlap, rapid main/SI, all mold sequence/maps and remaining FNANO2013leads'),'Save real discovery and source-review progress')
 L.atomic(L.HERE/'fnano2013_counterpart_audit.json',json.dumps({'new_journal_records':1,'existing_source_reviews':1,'provisional_design_groups':['RDE0036'],'complete_source_certifications':0,'counts':L.counts(),'validation':L.validate()},indent=2)+'\n');print(L.validate())
if __name__=='__main__':main()
